        mov     byte [putChar__c], 58
        call    putChar
; ---- putNumber( findCol() )
        call    findCol
        mov     ax, [findCol__ret]
        mov     [putNumber__n], ax
        call    putNumber
        jmp     .L230
.L229:
; ---- putChar( '-' )
        mov     byte [putChar__c], 45
        call    putChar
.L230:
; ---- newline()
        call    newline
        ret

; ============================================== sub showPrev ====

showPrev:
; ---- if ( findPrev( ln, col ) ) {
        mov     ax, [showPrev__ln]
        mov     [findPrev__ln], ax
        mov     ax, [showPrev__col]
