        mov     ax, [findLine__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ':' )
        mov     byte [putChar__c], 58
        call    putChar
; ---- putNumber( findCol() )
        call    findCol
        mov     ax, [findCol__ret]
        mov     [putNumber__n], ax
        call    putNumber
        jmp     .L233
.L232:
; ---- putChar( '-' )
        mov     byte [putChar__c], 45
        call    putChar
.L233:
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        ret

